import React, { ReactNode, useEffect, useState, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useAnimation } from './AnimationQueue';

interface AnimatedContentProps {
  children: ReactNode;
  routeKey: string; // Used to trigger animations on route changes
  className?: string;
  priority?: number; // Priority for the animation queue
  name?: string; // Name for the animation (for dependencies)
}

const DEBUG = false;

/**
 * AnimatedContent component that provides:
 * 1. Page transitions (fade in/out)
 * 2. Container for children with coordinated animations
 * 3. Integration with the animation queue
 */
const AnimatedContent: React.FC<AnimatedContentProps> = ({ 
  children, 
  routeKey,
  className = '',
  priority = 10, // Highest priority by default
  name = 'page-content'
}) => {
  const [showContent, setShowContent] = useState(false);
  const animationIdRef = useRef<string | null>(null);

  // Get animation context
  const { registerAnimation, completeAnimation, resetQueue } = useAnimation();

  // Handle page transitions and animation queue reset
  useEffect(() => {
    // Reset queue on route change
    resetQueue();

    // Hide content initially to transition in
    setShowContent(false);

    // Register this animation with the queue
    const handleStart = () => {
      if (DEBUG) console.log(`Starting page content animation: ${name}`);

      // Show content after a very short delay
      setTimeout(() => {
        setShowContent(true);
      }, 50);
    };

    const handleComplete = () => {
      if (DEBUG) console.log(`Completed page content animation: ${name}`);
    };

    // Register with high priority to ensure it runs first
    const animationId = registerAnimation('component', {
      priority,
      dependencies: [],
      onStart: handleStart,
      onComplete: handleComplete,
      name
    });

    animationIdRef.current = animationId;

    // Fallback to ensure content is shown even if queue fails
    // Use a longer timeout since we've improved the queue logic
    const fallbackTimer = setTimeout(() => {
      if (!showContent) {
        if (DEBUG) console.log(`Fallback triggered for page content: ${name}`);
        setShowContent(true);
      }
    }, 2000);

    // Clean up function
    return () => {
      if (animationIdRef.current) {
        completeAnimation(animationIdRef.current);
      }
      clearTimeout(fallbackTimer);
    };
  }, [routeKey, resetQueue, registerAnimation, completeAnimation, priority, name]);

  // Handle animation completion
  useEffect(() => {
    if (showContent && animationIdRef.current) {
      // Mark as complete after a short delay to ensure transition is visible
      const timer = setTimeout(() => {
        if (DEBUG) console.log(`Marking page content complete: ${name}`);
        completeAnimation(animationIdRef.current!);
      }, 300);

      return () => clearTimeout(timer);
    }
  }, [showContent, completeAnimation, name]);

  // Page transition variants
  const pageVariants = {
    initial: { opacity: 0 },
    animate: { opacity: 1, transition: { duration: 0.2 } },
    exit: { opacity: 0, transition: { duration: 0.1 } }
  };

  // Instead of a parallel fallback content, use a simpler approach:
  // Just ensure content is always shown after a timeout
  useEffect(() => {
    const timer = setTimeout(() => {
      if (!showContent) {
        if (DEBUG) console.log(`Emergency fallback triggered for page content: ${name}`);
        setShowContent(true);
      }
    }, 5000); // Long emergency timeout

    return () => clearTimeout(timer);
  }, [showContent, name]);

  return (
    <AnimatePresence mode="wait">
      {showContent ? (
        <motion.div
          key={`animated-content-${routeKey}`}
          initial="initial"
          animate="animate"
          exit="exit"
          variants={pageVariants}
          className={`animated-content-wrapper ${className}`}
        >
          {children}
        </motion.div>
      ) : (
        // Loading indicator while content is initializing
        <div className="content-loading">
          <span className="sr-only">Loading content...</span>
        </div>
      )}
    </AnimatePresence>
  );
};

export default AnimatedContent;
